with accounts_by_customer as (select customer_id, round((100 * sum(case when account_type = 'SAVINGS' then 1 else 0 end)) / count(*), 1) as pct_savings from accounts where account_type in ('LOAN', 'CHECKING', 'SAVINGS') group by customer_id) select c.id, c.email, abc.pct_savings from customers c left outer join accounts_by_customer abc on c.id = abc.customer_id where abc.pct_savings > 51 order by pct_savings
